ALTER TABLE products ADD COLUMN setup_issues TEXT NOT NULL DEFAULT '[]';
ALTER TABLE products ADD COLUMN is_tea INTEGER NOT NULL DEFAULT 0;
ALTER TABLE products ADD COLUMN group_id INTEGER;
CREATE TABLE product_groups(id INTEGER PRIMARY KEY,name TEXT NOT NULL UNIQUE);
ALTER TABLE stock_lots ADD COLUMN unit_base INTEGER NOT NULL DEFAULT 1;
ALTER TABLE sale_items ADD COLUMN snapshot TEXT NOT NULL DEFAULT '{}';
ALTER TABLE sales ADD COLUMN snapshot TEXT NOT NULL DEFAULT '{}';
ALTER TABLE sales ADD COLUMN van_id INTEGER;
ALTER TABLE sales ADD COLUMN sealed INTEGER NOT NULL DEFAULT 0;
ALTER TABLE returns ADD COLUMN reversed_at INTEGER;
ALTER TABLE returns ADD COLUMN van_id INTEGER;
CREATE TABLE return_lots(id INTEGER PRIMARY KEY,return_item_id INTEGER NOT NULL REFERENCES return_items(id),sale_item_lot_id INTEGER NOT NULL REFERENCES sale_item_lots(id),qty INTEGER NOT NULL,cost INTEGER NOT NULL);
ALTER TABLE expenses ADD COLUMN method TEXT NOT NULL DEFAULT 'cash';
ALTER TABLE expenses ADD COLUMN reversed_at INTEGER;
ALTER TABLE expenses ADD COLUMN source TEXT;
ALTER TABLE expenses ADD COLUMN source_id INTEGER;
CREATE TABLE cash_movements(id INTEGER PRIMARY KEY,date TEXT NOT NULL,ts INTEGER NOT NULL,amount INTEGER NOT NULL,method TEXT NOT NULL,source TEXT NOT NULL,source_id INTEGER NOT NULL,user_id INTEGER NOT NULL,UNIQUE(source,source_id));
CREATE TABLE refunds(id INTEGER PRIMARY KEY,customer_id INTEGER NOT NULL REFERENCES customers(id),amount INTEGER NOT NULL,method TEXT NOT NULL,reason TEXT NOT NULL,date TEXT NOT NULL,ts INTEGER NOT NULL,created_by INTEGER NOT NULL);
CREATE TABLE credit_applications(id INTEGER PRIMARY KEY,customer_id INTEGER NOT NULL REFERENCES customers(id),sale_id INTEGER NOT NULL REFERENCES sales(id),amount INTEGER NOT NULL,active INTEGER NOT NULL DEFAULT 1,date TEXT NOT NULL);
ALTER TABLE approvals ADD COLUMN payload_hash TEXT;
ALTER TABLE cash_closes ADD COLUMN revision INTEGER NOT NULL DEFAULT 1;
ALTER TABLE cash_closes ADD COLUMN reopened INTEGER NOT NULL DEFAULT 0;
CREATE TABLE cash_close_revisions(id INTEGER PRIMARY KEY,date TEXT NOT NULL,revision INTEGER NOT NULL,snapshot TEXT NOT NULL,reason TEXT NOT NULL,ts INTEGER NOT NULL,UNIQUE(date,revision));
ALTER TABLE load_sheets ADD COLUMN snapshot TEXT;
ALTER TABLE commission_rules ADD COLUMN effective_from TEXT NOT NULL DEFAULT '1970-01-01';
CREATE UNIQUE INDEX ux_commission_period ON commission_accruals(rule_id,period_start);
CREATE TABLE commission_adjustments(id INTEGER PRIMARY KEY,rule_id INTEGER NOT NULL REFERENCES commission_rules(id),source TEXT NOT NULL,source_id INTEGER NOT NULL,grams INTEGER NOT NULL,period_start TEXT NOT NULL,UNIQUE(rule_id,source,source_id));
CREATE TABLE counters(name TEXT PRIMARY KEY,value INTEGER NOT NULL);
CREATE TABLE requests(user_id INTEGER NOT NULL,request_id TEXT NOT NULL,method TEXT NOT NULL,payload_hash TEXT NOT NULL,result TEXT NOT NULL,PRIMARY KEY(user_id,request_id));
CREATE TABLE backup_paths(id TEXT PRIMARY KEY,path TEXT NOT NULL);
CREATE TABLE auth_limits(key TEXT PRIMARY KEY,tries INTEGER NOT NULL DEFAULT 0,until_ts INTEGER NOT NULL DEFAULT 0);
CREATE TABLE opening_cutovers(party_type TEXT NOT NULL,party_id INTEGER NOT NULL,date TEXT NOT NULL,PRIMARY KEY(party_type,party_id));
CREATE TRIGGER sales_core_immutable BEFORE UPDATE OF invoice_no,date,ts,customer_id,subtotal,line_discount,invoice_discount_type,invoice_discount_input,invoice_discount,total,paid,salesman_id,created_by,snapshot,van_id ON sales WHEN OLD.sealed=1 BEGIN SELECT RAISE(ABORT,'saved invoice immutable'); END;
CREATE TRIGGER sales_no_unseal BEFORE UPDATE OF sealed ON sales WHEN OLD.sealed=1 BEGIN SELECT RAISE(ABORT,'sealed'); END;
CREATE TRIGGER items_no_insert_sealed BEFORE INSERT ON sale_items WHEN (SELECT sealed FROM sales WHERE id=NEW.sale_id)=1 BEGIN SELECT RAISE(ABORT,'sealed'); END;
CREATE TRIGGER items_no_reassign BEFORE UPDATE OF sale_id,line_no,snapshot ON sale_items BEGIN SELECT RAISE(ABORT,'saved line immutable'); END;
CREATE TRIGGER allocation_no_update BEFORE UPDATE ON payment_allocations BEGIN SELECT RAISE(ABORT,'allocation immutable'); END;
CREATE TRIGGER allocation_no_delete BEFORE DELETE ON payment_allocations BEGIN SELECT RAISE(ABORT,'allocation immutable'); END;
CREATE TRIGGER payments_metadata_immutable BEFORE UPDATE OF ts,ref,note,created_by ON payments BEGIN SELECT RAISE(ABORT,'payment immutable'); END;
CREATE TRIGGER expenses_immutable BEFORE UPDATE OF date,ts,type,amount,note,created_by,method ON expenses BEGIN SELECT RAISE(ABORT,'expense immutable'); END;
CREATE TRIGGER expenses_no_delete BEFORE DELETE ON expenses BEGIN SELECT RAISE(ABORT,'expense immutable'); END;
CREATE TRIGGER cash_move_no_update BEFORE UPDATE ON cash_movements BEGIN SELECT RAISE(ABORT,'cash immutable'); END;
CREATE TRIGGER cash_move_no_delete BEFORE DELETE ON cash_movements BEGIN SELECT RAISE(ABORT,'cash immutable'); END;
CREATE INDEX ix_alloc_sale ON payment_allocations(sale_id);
CREATE INDEX ix_alloc_purchase ON payment_allocations(purchase_id);
CREATE INDEX ix_items_sale2 ON sale_items(sale_id);
CREATE INDEX ix_items_product2 ON sale_items(product_id);
CREATE INDEX ix_return_sale ON returns(sale_id,status);
CREATE INDEX ix_cash_date ON cash_movements(date);
